        "titolo_orig": "Guinea-Bissau: Opposition leader house arrest raises stakes",
        "testo_it": "In Guinea-Bissau cresce la tensione per il prolungato arresto domiciliare dell'oppositore Pereira.",
        "priorita": "Bassa",
        "id_gruppo": 7,
        "link": "https://www.dw.com/en/guinea-bissau-opposition-leader-house-arrest-raises-stakes/a-77593866?maca=en-rss-en-world-4025-rdf",
